# Python 版本解法
import sys

def main():
    import sys
    input_data = sys.stdin.read().split()
    t = int(input_data[0])
    index = 1
    res = []
    for _ in range(t):
        n = int(input_data[index])
        index += 1
        a = list(map(int, input_data[index:index+n]))
        index += n
        freq = {0: 1}  # 用字典统计前缀和出现次数
        prefix = 0
        ans = 0
        # 遍历数组计算前缀和
        for num in a:
            prefix += num
            # 枚举可能的 k 值, 计算 2^k
            for k in range(1, 60):
                power = 1 << k  # 计算 2^k
                target = prefix - power
                if target in freq:
                    ans += k * freq[target]
            freq[prefix] = freq.get(prefix, 0) + 1
        res.append(str(ans))
    sys.stdout.write("\n".join(res))

if __name__ == '__main__':
    main()
