import java.io.*;
import java.util.*;

// Java 版本解法
public class Main {
    public static void main(String[] args) throws IOException {
        // 使用 BufferedReader 和 PrintWriter 提高输入输出效率
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));
        int T = Integer.parseInt(br.readLine().trim());
        while(T-- > 0){
            int n = Integer.parseInt(br.readLine().trim());
            String[] parts = br.readLine().trim().split(" ");
            long[] a = new long[n];
            for(int i = 0; i < n; i++){
                a[i] = Long.parseLong(parts[i]);
            }
            // 使用 HashMap 统计前缀和出现次数
            HashMap<Long, Long> freq = new HashMap<>();
            freq.put(0L, 1L); // 前缀和 0 出现一次
            long prefix = 0;
            long ans = 0;
            // 遍历数组计算前缀和
            for(int i = 0; i < n; i++){
                prefix += a[i];
                // 枚举可能的 k 值, 计算 2^k
                for(int k = 1; k < 60; k++){
                    long power = 1L << k; // 计算 2^k
                    long target = prefix - power;
                    if(freq.containsKey(target)){
                        ans += k * freq.get(target);
                    }
                }
                freq.put(prefix, freq.getOrDefault(prefix, 0L) + 1);
            }
            out.println(ans);
        }
        out.flush();
        out.close();
    }
}
